            archive_write_free(out);
            archive_read_free(src);
            return false;
        }

        // Create full path
        char *full_path = malloc(strlen(dest_path) + strlen(entry_path) + 2);
        if (!full_path) {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }
        snprintf(full_path, strlen(dest_path) + strlen(entry_path) + 2, "%s/%s", dest_path, entry_path);
        archive_entry_set_pathname(entry, full_path);

        // Write header
        r = archive_write_header(out, entry);
        if (r != ARCHIVE_OK) {
            free(full_path);
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }

        // Copy data
        const void *buff;
        size_t size;
        la_int64_t offset;
        while ((r = archive_read_data_block(src, &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out, buff, size, offset) != ARCHIVE_OK) {
                free(full_path);
                archive_write_free(out);
                archive_read_free(src);
                return false;
            }
        }
        free(full_path);
        if (r != ARCHIVE_EOF) {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }
    }

    archive_write_free(out);
    archive_read_free(src);
    return r == ARCHIVE_EOF ? true : false;
}
